import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxDivider,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type StatusValue = 'active' | 'risk' | 'over' | 'archived';

interface SpendProject {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: StatusValue;
}

interface ProjectSpendPanelProps {
  projects?: SpendProject[];
}

const STATUSES: Array<{
  value: StatusValue;
  label: string;
  tone: 'success' | 'warning' | 'danger' | 'default';
}> = [
  { value: 'active', label: 'В норме', tone: 'success' },
  { value: 'risk', label: 'Близко к лимиту', tone: 'warning' },
  { value: 'over', label: 'Перерасход', tone: 'danger' },
  { value: 'archived', label: 'Архив', tone: 'default' },
];

const DEFAULT_PROJECTS: SpendProject[] = [
  { id: 'p1', name: 'Контекстная лаборатория', used: 412, quota: 1000, status: 'active' },
  { id: 'p2', name: 'Поисковый индекс документации', used: 870, quota: 1000, status: 'risk' },
  { id: 'p3', name: 'Витрина отчётов для финансов', used: 1180, quota: 1000, status: 'over' },
  { id: 'p4', name: 'Мобильный клиент', used: 240, quota: 800, status: 'active' },
  { id: 'p5', name: 'Импорт из внешних CRM', used: 690, quota: 750, status: 'risk' },
  { id: 'p6', name: 'Экспериментальный ранжировщик', used: 95, quota: 500, status: 'archived' },
  { id: 'p7', name: 'Аналитика оттока пользователей', used: 530, quota: 900, status: 'active' },
  { id: 'p8', name: 'Миграция биллинга', used: 1440, quota: 1200, status: 'over' },
  { id: 'p9', name: 'Прогон регрессионных тестов', used: 310, quota: 400, status: 'risk' },
  { id: 'p10', name: 'Старый портал партнёров', used: 60, quota: 600, status: 'archived' },
  { id: 'p11', name: 'Синхронизация справочников', used: 355, quota: 700, status: 'active' },
  { id: 'p12', name: 'Черновик нового онбординга', used: 20, quota: 300, status: 'archived' },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel({ projects = DEFAULT_PROJECTS }: ProjectSpendPanelProps) {
  const [selected, setSelected] = useState<StatusValue[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: StatusValue) => {
    setSelected((current) =>
      current.includes(status) ? current.filter((item) => item !== status) : [...current, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setSelected([]);
    setPage(1);
  };

  const filtered = useMemo(
    () => (selected.length === 0 ? projects : projects.filter((project) => selected.includes(project.status))),
    [projects, selected],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  return (
    <section
      aria-label="Расход по проектам"
      style={{ display: 'flex', flexDirection: 'column', gap: '16px', fontFamily: 'var(--jx-font-sans)' }}
    >
      <div role="group" aria-label="Фильтр по статусу" style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUSES.map((status) => {
          const isActive = selected.includes(status.value);
          return (
            <JxChip
              key={status.value}
              role="button"
              tabIndex={0}
              aria-pressed={isActive}
              active={isActive}
              removable={isActive}
              onRemove={() => toggleStatus(status.value)}
              onClick={() => toggleStatus(status.value)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  toggleStatus(status.value);
                }
              }}
            >
              {status.label}
            </JxChip>
          );
        })}
      </div>

      <JxDivider />

      {filtered.length === 0 ? (
        <JxEmptyState
          title="Под фильтры ничего не подошло"
          message="Ни один проект не попадает в выбранные статусы. Снимите фильтры, чтобы увидеть весь список."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '4px',
              listStyle: 'none',
              margin: 0,
              padding: 0,
            }}
          >
            {visible.map((project) => {
              const status = STATUSES.find((item) => item.value === project.status);
              const percent = Math.round((project.used / project.quota) * 100);
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px',
                    borderRadius: 'var(--jx-r)',
                    background: 'var(--jx-surface)',
                    border: '1px solid var(--jx-border)',
                  }}
                >
                  <JxProgressCircle
                    value={percent}
                    max={100}
                    showValue
                    aria-label={`Квота проекта «${project.name}» заполнена на ${percent} процентов`}
                  />
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '2px', minWidth: 0, flex: 1 }}>
                    <span
                      style={{
                        color: 'var(--jx-text)',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}
                    >
                      {project.name}
                    </span>
                    <span style={{ color: 'var(--jx-text-2)', fontSize: '0.875rem' }}>
                      {project.used} из {project.quota}
                    </span>
                  </div>
                  <JxBadge tone={status?.tone ?? 'default'} dot>
                    {status?.label ?? 'Без статуса'}
                  </JxBadge>
                </li>
              );
            })}
          </ul>

          <JxPagination
            aria-label="Страницы списка проектов"
            total={pageCount}
            page={currentPage}
            onPageChange={setPage}
          />
        </>
      )}
    </section>
  );
}

